//! `minting.yaml` (#168): the Egress Daemon's credential-minting settings.
//!
//! Operator-owned and never regenerated by `maknae enroll`. It is a separate
//! document from `egress-bounds.yaml` so rewriting the bounds cannot erase it.

use crate::{ConfigError, ForgeProvider, Value};
use std::collections::BTreeMap;
use std::path::Path;

pub const MINTING_FILE: &str = "minting.yaml";

const NAME_MAX: usize = 64;

pub const MAX_APIS: usize = 32;

/// The whole file. Every App's `host` names an `apis` entry whose `api` it shares.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct MintingFile {
    apis: BTreeMap<String, ForgeApi>,
    minting: Option<MintingConfig>,
}

impl MintingFile {
    pub fn apis(&self) -> &BTreeMap<String, ForgeApi> {
        &self.apis
    }

    pub fn api(&self, host: &str) -> Option<&ForgeApi> {
        self.apis.get(host)
    }

    /// `None` unless the file has a `vault` mapping: `apis` alone enables no minting.
    pub fn minting(&self) -> Option<&MintingConfig> {
        self.minting.as_ref()
    }

    pub fn into_minting(self) -> Option<MintingConfig> {
        self.minting
    }
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct ForgeApi {
    pub provider: ForgeProvider,
    pub api: ApiBase,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct MintingConfig {
    pub vault: MintVault,
    pub github_apps: BTreeMap<String, GithubAppConfig>,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct MintVault {
    pub approle_mount: String,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct GithubAppConfig {
    pub app_id: u64,
    pub installation_id: u64,
    pub host: String,
    pub api: ApiBase,
    pub transit_mount: String,
    pub transit_key: String,
}

/// `https://host[:port]`, no trailing slash, path, query, userinfo or fragment.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct ApiBase(String);

impl ApiBase {
    pub fn parse(text: &str) -> Option<ApiBase> {
        let rest = text.strip_prefix("https://")?;
        let authority = rest.strip_suffix('/').unwrap_or(rest);
        if authority.contains(['/', '?', '#', '@', '\\']) {
            return None;
        }
        // Host and port grammar are the providers' (`endpoint_is_acceptable`); the
        // exclusions above leave it nothing but `host[:port]` to judge.
        crate::endpoint_is_acceptable(&format!("https://{authority}"))
            .then(|| ApiBase(format!("https://{authority}")))
    }

    pub fn as_str(&self) -> &str {
        &self.0
    }
}

fn err(reason: impl Into<String>) -> ConfigError {
    ConfigError::InvalidMinting(reason.into())
}

fn field<'a>(m: &'a [(String, Value)], name: &str) -> Option<&'a Value> {
    m.iter().find(|(k, _)| k == name).map(|(_, v)| v)
}

fn string_field(
    m: &[(String, Value)],
    at: &str,
    name: &str,
    grammar: impl Fn(&str) -> bool,
) -> Result<String, ConfigError> {
    match field(m, name) {
        Some(Value::Str(v)) if grammar(v) => Ok(v.clone()),
        Some(Value::Str(_)) => Err(err(format!("'{at}{name}' is outside its grammar"))),
        Some(_) => Err(err(format!("'{at}{name}' must be a string"))),
        None => Err(err(format!("'{at}{name}' is required"))),
    }
}

fn id_field(m: &[(String, Value)], at: &str, name: &str) -> Result<u64, ConfigError> {
    match field(m, name) {
        Some(Value::Int(n)) if *n > 0 => Ok(*n as u64),
        Some(Value::Int(_)) => Err(err(format!("'{at}{name}' must be positive"))),
        Some(_) => Err(err(format!("'{at}{name}' must be an integer"))),
        None => Err(err(format!("'{at}{name}' is required"))),
    }
}

fn mount_or_key(s: &str) -> bool {
    (1..=NAME_MAX).contains(&s.len())
        && s.bytes()
            .all(|b| b.is_ascii_alphanumeric() || b == b'_' || b == b'-')
}

fn app_name(s: &str) -> bool {
    (1..=NAME_MAX).contains(&s.len())
        && s.bytes()
            .all(|b| b.is_ascii_lowercase() || b.is_ascii_digit() || b == b'-')
}

fn apis_from(m: &[(String, Value)]) -> Result<BTreeMap<String, ForgeApi>, ConfigError> {
    let entries = match field(m, "apis") {
        None => return Ok(BTreeMap::new()),
        Some(Value::Map(entries)) => entries,
        Some(_) => return Err(err("'apis' must be a mapping")),
    };
    if entries.len() > MAX_APIS {
        return Err(err(format!("'apis' may list at most {MAX_APIS} hosts")));
    }
    let mut apis = BTreeMap::new();
    for (host, entry) in entries {
        if host.bytes().any(|b| b.is_ascii_uppercase()) || !maknae_proto::server_is_acceptable(host)
        {
            return Err(err("an 'apis' host is outside its grammar"));
        }
        let Value::Map(em) = entry else {
            return Err(err(format!("'apis.{host}' must be a mapping")));
        };
        crate::reject_unknown_keys(
            &format!("{MINTING_FILE}/apis.{host}"),
            em,
            &["provider", "api"],
        )?;
        let at = format!("apis.{host}.");
        let provider = string_field(em, &at, "provider", |s| ForgeProvider::parse(s).is_some())?;
        let api = string_field(em, &at, "api", |s| ApiBase::parse(s).is_some())?;
        apis.insert(
            host.clone(),
            ForgeApi {
                provider: ForgeProvider::parse(&provider)
                    .ok_or_else(|| err("'provider' is invalid"))?,
                api: ApiBase::parse(&api).ok_or_else(|| err("'api' is invalid"))?,
            },
        );
    }
    Ok(apis)
}

fn github_app(
    name: &str,
    entry: &Value,
    apis: &BTreeMap<String, ForgeApi>,
) -> Result<GithubAppConfig, ConfigError> {
    if !app_name(name) {
        return Err(err("a 'github_apps' name is outside its grammar"));
    }
    let Value::Map(am) = entry else {
        return Err(err(format!("'github_apps.{name}' must be a mapping")));
    };
    crate::reject_unknown_keys(
        &format!("{MINTING_FILE}/github_apps.{name}"),
        am,
        &[
            "app_id",
            "installation_id",
            "host",
            "api",
            "transit_mount",
            "transit_key",
        ],
    )?;
    let at = format!("github_apps.{name}.");
    let host = string_field(am, &at, "host", |h| {
        apis.get(h)
            .is_some_and(|a| a.provider == ForgeProvider::Github)
    })?;
    let api = string_field(am, &at, "api", |s| ApiBase::parse(s).is_some())?;
    let api = ApiBase::parse(&api).ok_or_else(|| err("'api' is invalid"))?;
    if apis.get(&host).map(|a| &a.api) != Some(&api) {
        return Err(err(format!("'{at}api' differs from 'apis.{host}.api'")));
    }
    Ok(GithubAppConfig {
        app_id: id_field(am, &at, "app_id")?,
        installation_id: id_field(am, &at, "installation_id")?,
        host,
        api,
        transit_mount: string_field(am, &at, "transit_mount", mount_or_key)?,
        transit_key: string_field(am, &at, "transit_key", mount_or_key)?,
    })
}

pub fn minting_from_document(v: &Value) -> Result<MintingFile, ConfigError> {
    let Value::Map(m) = v else {
        return Err(err("expected a mapping at the top level"));
    };
    crate::reject_unknown_keys(MINTING_FILE, m, &["vault", "apis", "github_apps"])?;
    let apis = apis_from(m)?;
    let vault = match field(m, "vault") {
        None if field(m, "github_apps").is_some() => {
            return Err(err("'github_apps' requires the 'vault' mapping"))
        }
        None => {
            return Ok(MintingFile {
                apis,
                minting: None,
            })
        }
        Some(Value::Map(vm)) => vm,
        Some(_) => return Err(err("'vault' must be a mapping")),
    };
    crate::reject_unknown_keys(&format!("{MINTING_FILE}/vault"), vault, &["approle_mount"])?;
    let vault = MintVault {
        approle_mount: string_field(vault, "vault.", "approle_mount", mount_or_key)?,
    };
    let github_apps = match field(m, "github_apps") {
        None => BTreeMap::new(),
        Some(Value::Map(entries)) => entries
            .iter()
            .map(|(name, entry)| Ok((name.clone(), github_app(name, entry, &apis)?)))
            .collect::<Result<_, ConfigError>>()?,
        Some(_) => return Err(err("'github_apps' must be a mapping")),
    };
    Ok(MintingFile {
        apis,
        minting: Some(MintingConfig { vault, github_apps }),
    })
}

/// `root:_maknae-egress 0640`. The loader holds the owner to root and refuses
/// every bit beyond 0640; it cannot name the group, which enroll sets.
const MINTING_MAX_BYTES: usize = 64 * 1024;

#[cfg(unix)]
const MINTING_ARTIFACT: maknae_io::TargetRequired = maknae_io::TargetRequired {
    owner: Some(0),
    mode_mask: Some(0o137),
    nlink_exactly_one: false,
    regular_file: true,
    max_bytes: Some(MINTING_MAX_BYTES as u64),
};

#[cfg(unix)]
fn load_minting_with(
    path: &Path,
    requirement: maknae_io::TargetRequired,
) -> Result<Option<MintingFile>, ConfigError> {
    match crate::loader::read_secure_required(path, requirement) {
        Ok(text) => minting_from_document(&crate::load_str(&text)?).map(Some),
        Err(ConfigError::NotFound { .. }) => Ok(None),
        Err(e) => Err(e),
    }
}

pub const MINT_ROLE_ID_FILE: &str = "role-id";

const ROLE_ID_MAX_BYTES: usize = 128;

#[cfg(unix)]
const ROLE_ID_ARTIFACT: maknae_io::TargetRequired = maknae_io::TargetRequired {
    max_bytes: Some(ROLE_ID_MAX_BYTES as u64 + 2),
    ..MINTING_ARTIFACT
};

#[cfg(unix)]
fn load_mint_role_id_with(
    path: &Path,
    requirement: maknae_io::TargetRequired,
) -> Result<String, ConfigError> {
    let text = crate::loader::read_secure_required(path, requirement)?;
    let role = text.trim();
    if !(1..=ROLE_ID_MAX_BYTES).contains(&role.len()) {
        return Err(ConfigError::InvalidMintRoleId("empty or too long"));
    }
    if !role.bytes().all(|b| b.is_ascii_graphic()) {
        return Err(ConfigError::InvalidMintRoleId(
            "a byte outside printable ASCII",
        ));
    }
    Ok(role.to_owned())
}

/// The Egress Daemon's AppRole role id, beside `minting.yaml` and held to its owner and mode.
pub fn load_mint_role_id(path: &Path) -> Result<String, ConfigError> {
    #[cfg(not(unix))]
    {
        let _ = path;
        Err(ConfigError::PermissionsUnsupported)
    }
    #[cfg(unix)]
    {
        load_mint_role_id_with(path, ROLE_ID_ARTIFACT)
    }
}

pub fn load_minting(path: &Path) -> Result<Option<MintingFile>, ConfigError> {
    #[cfg(not(unix))]
    {
        let _ = path;
        Err(ConfigError::PermissionsUnsupported)
    }
    #[cfg(unix)]
    {
        load_minting_with(path, MINTING_ARTIFACT)
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::os::unix::fs::{MetadataExt, PermissionsExt};
    use std::path::PathBuf;

    const FULL: &str = concat!(
        "vault:\n",
        "  approle_mount: approle-mint\n",
        "apis:\n",
        "  github.com:\n",
        "    provider: github\n",
        "    api: https://api.github.com\n",
        "  ghe.example:\n",
        "    provider: github\n",
        "    api: https://ghe.example:8443\n",
        "github_apps:\n",
        "  ci-bot:\n",
        "    app_id: 12345\n",
        "    installation_id: 67890\n",
        "    host: github.com\n",
        "    api: https://api.github.com\n",
        "    transit_mount: transit\n",
        "    transit_key: gh-app_1\n",
        "  ghe:\n",
        "    app_id: 7\n",
        "    installation_id: 8\n",
        "    host: ghe.example\n",
        "    api: https://ghe.example:8443/\n",
        "    transit_mount: transit-ghe\n",
        "    transit_key: key-2\n",
    );

    fn parse_file(text: &str) -> Result<MintingFile, ConfigError> {
        minting_from_document(&crate::load_str(text).unwrap())
    }

    fn parse(text: &str) -> Result<MintingConfig, ConfigError> {
        parse_file(text).map(|f| f.into_minting().expect("minting is enabled"))
    }

    const X_API: &str = "apis:\n  x.example:\n    provider: github\n    api: https://x.example\n";

    fn app(api: &str, mount: &str, key: &str) -> String {
        format!(
            "vault:\n  approle_mount: m\napis:\n  x.example:\n    provider: github\n    api: \"{api}\"\ngithub_apps:\n  a:\n    app_id: 1\n    installation_id: 2\n    host: x.example\n    api: \"{api}\"\n    transit_mount: {mount}\n    transit_key: {key}\n"
        )
    }

    #[test]
    fn apis_map_hosts_to_provider_and_api() {
        let f = parse_file(FULL).unwrap();
        assert_eq!(f.apis().len(), 2);
        let gh = f.api("github.com").unwrap();
        assert_eq!(gh.provider, ForgeProvider::Github);
        assert_eq!(gh.api.as_str(), "https://api.github.com");
        assert_eq!(
            f.api("ghe.example").unwrap().api.as_str(),
            "https://ghe.example:8443"
        );
        assert!(f.api("gitlab.com").is_none());
        let m = f.minting().unwrap();
        assert_eq!(m.github_apps["ci-bot"].host, "github.com");
        assert_eq!(m.github_apps["ghe"].host, "ghe.example");
        assert_eq!(MAX_APIS, 32);
    }

    #[test]
    fn an_app_whose_host_names_no_api_refuses_the_load() {
        let text = format!(
            "vault:\n  approle_mount: m\n{X_API}github_apps:\n  a:\n    app_id: 1\n    installation_id: 2\n    host: y.example\n    api: https://x.example\n    transit_mount: t\n    transit_key: k\n"
        );
        let e = parse_file(&text).unwrap_err().to_string();
        assert!(e.contains("github_apps.a.host"), "{e}");
        let missing = format!(
            "vault:\n  approle_mount: m\n{X_API}github_apps:\n  a:\n    app_id: 1\n    installation_id: 2\n    api: https://x.example\n    transit_mount: t\n    transit_key: k\n"
        );
        assert!(parse_file(&missing).is_err());
        let gitlab = "vault:\n  approle_mount: m\napis:\n  x.example:\n    provider: gitlab\n    api: https://x.example\ngithub_apps:\n  a:\n    app_id: 1\n    installation_id: 2\n    host: x.example\n    api: https://x.example\n    transit_mount: t\n    transit_key: k\n";
        assert!(parse_file(gitlab).is_err());
    }

    #[test]
    fn an_app_whose_api_differs_from_its_host_api_refuses_the_load() {
        let text = format!(
            "vault:\n  approle_mount: m\n{X_API}github_apps:\n  a:\n    app_id: 1\n    installation_id: 2\n    host: x.example\n    api: https://x.example:8443\n    transit_mount: t\n    transit_key: k\n"
        );
        let e = parse_file(&text).unwrap_err().to_string();
        assert!(e.contains("github_apps.a.api"), "{e}");
        let trailing = format!(
            "vault:\n  approle_mount: m\n{X_API}github_apps:\n  a:\n    app_id: 1\n    installation_id: 2\n    host: x.example\n    api: https://x.example/\n    transit_mount: t\n    transit_key: k\n"
        );
        assert!(parse_file(&trailing).is_ok());
    }

    #[test]
    fn apis_alone_need_no_vault_and_enable_no_minting() {
        let f = parse_file(X_API).unwrap();
        assert!(f.minting().is_none());
        assert_eq!(f.api("x.example").unwrap().provider, ForgeProvider::Github);
        assert!(parse_file("{}\n").unwrap().into_minting().is_none());
        let apps_without_vault = format!(
            "{X_API}github_apps:\n  a:\n    app_id: 1\n    installation_id: 2\n    host: x.example\n    api: https://x.example\n    transit_mount: t\n    transit_key: k\n"
        );
        let e = parse_file(&apps_without_vault).unwrap_err().to_string();
        assert!(e.contains("vault"), "{e}");
        assert!(parse_file(&format!("{X_API}github_apps: {{}}\n")).is_err());
        assert!(parse_file("vault:\n  approle_mount: m\n")
            .unwrap()
            .minting()
            .is_some());
    }

    #[test]
    fn apis_are_bounded_and_held_to_their_grammar() {
        let entry =
            |h: &str| format!("  \"{h}\":\n    provider: github\n    api: https://x.example\n");
        let many = |n: usize| {
            let mut t = String::from("apis:\n");
            for i in 0..n {
                t.push_str(&entry(&format!("h{i}.example")));
            }
            t
        };
        assert_eq!(parse_file(&many(MAX_APIS)).unwrap().apis().len(), 32);
        assert!(parse_file(&many(MAX_APIS + 1)).is_err());
        for h in ["", "GitHub.com", "a b", "https://x.example", "x.example/p"] {
            assert!(
                parse_file(&format!("apis:\n{}", entry(h))).is_err(),
                "host {h:?}"
            );
        }
        for bad in [
            "apis: x\n",
            "apis:\n  x.example: x\n",
            "apis:\n  x.example:\n    api: https://x.example\n",
            "apis:\n  x.example:\n    provider: bitbucket\n    api: https://x.example\n",
            "apis:\n  x.example:\n    provider: github\n",
            "apis:\n  x.example:\n    provider: github\n    api: http://x.example\n",
        ] {
            assert!(parse_file(bad).is_err(), "{bad}");
        }
        let e = parse_file(
            "apis:\n  x.example:\n    provider: github\n    api: https://x.example\n    token: t\n",
        )
        .unwrap_err();
        assert!(
            matches!(&e, ConfigError::UnknownKey { key, .. } if key == "token"),
            "{e:?}"
        );
    }

    fn tmp(name: &str) -> PathBuf {
        std::env::temp_dir().join(format!("maknae_mint_{name}_{}", std::process::id()))
    }

    fn write(name: &str, body: &str, mode: u32) -> PathBuf {
        let p = tmp(name);
        std::fs::write(&p, body).unwrap();
        std::fs::set_permissions(&p, std::fs::Permissions::from_mode(mode)).unwrap();
        p
    }

    fn me(p: &Path) -> u32 {
        std::fs::metadata(p).unwrap().uid()
    }

    #[test]
    fn a_missing_file_is_no_minting() {
        let p = tmp("absent");
        assert_eq!(
            load_minting_with(&p, requirement(me(&std::env::temp_dir()))),
            Ok(None)
        );
        assert_eq!(load_minting(&p), Ok(None));
    }

    #[test]
    fn the_production_loader_reads_a_present_file_held_to_root() {
        let p = write("present", FULL, 0o640);
        let (owner, got) = (me(&p), load_minting(&p));
        let _ = std::fs::remove_file(&p);
        if owner == 0 {
            assert_eq!(got, Ok(Some(parse_file(FULL).unwrap())));
        } else {
            assert_eq!(
                got,
                Err(ConfigError::Io(format!(
                    "owned by {owner}, require 0: {}",
                    p.display()
                )))
            );
        }
    }

    #[test]
    fn a_full_file_parses_to_the_pinned_values() {
        let got = parse(FULL).unwrap();
        assert_eq!(got.vault.approle_mount, "approle-mint");
        assert_eq!(got.github_apps.len(), 2);
        let ci = &got.github_apps["ci-bot"];
        assert_eq!(ci.app_id, 12345);
        assert_eq!(ci.installation_id, 67890);
        assert_eq!(ci.api.as_str(), "https://api.github.com");
        assert_eq!(ci.transit_mount, "transit");
        assert_eq!(ci.transit_key, "gh-app_1");
        assert_eq!(
            got.github_apps["ghe"].api.as_str(),
            "https://ghe.example:8443"
        );
        assert_eq!(MINTING_FILE, "minting.yaml");
    }

    #[test]
    fn an_empty_app_table_and_a_missing_one_are_both_valid() {
        assert!(parse("vault:\n  approle_mount: m\n")
            .unwrap()
            .github_apps
            .is_empty());
        assert!(parse("vault:\n  approle_mount: m\ngithub_apps: {}\n")
            .unwrap()
            .github_apps
            .is_empty());
    }

    #[test]
    fn unknown_keys_are_refused_at_every_level() {
        for (text, key) in [
            ("vault:\n  approle_mount: m\nextra: 1\n", "extra"),
            ("vault:\n  approle_mount: m\n  role_id: x\n", "role_id"),
            (
                "vault:\n  approle_mount: m\napis:\n  x.example:\n    provider: github\n    api: https://x.example\ngithub_apps:\n  a:\n    app_id: 1\n    installation_id: 2\n    host: x.example\n    api: https://x.example\n    transit_mount: t\n    transit_key: k\n    private_key: x\n",
                "private_key",
            ),
        ] {
            let got = parse(text).unwrap_err();
            assert!(
                matches!(&got, ConfigError::UnknownKey { key: k, .. } if k == key),
                "{text}: {got:?}"
            );
        }
    }

    #[test]
    fn required_keys_and_types_are_enforced() {
        let with_app = |fields: &str| {
            format!("vault:\n  approle_mount: m\n{X_API}github_apps:\n  a:\n{fields}    host: x.example\n    api: https://x.example\n    transit_mount: t\n    transit_key: k\n")
        };
        for text in [
            "github_apps: {}\n".to_string(),
            "vault: {}\n".to_string(),
            "vault:\n  approle_mount: 3\n".to_string(),
            "vault: x\n".to_string(),
            "- a\n".to_string(),
            "vault:\n  approle_mount: m\ngithub_apps: x\n".to_string(),
            "vault:\n  approle_mount: m\ngithub_apps:\n  a: x\n".to_string(),
            with_app("    installation_id: 2\n"),
            with_app("    app_id: 0\n    installation_id: 2\n"),
            with_app("    app_id: -1\n    installation_id: 2\n"),
            with_app("    app_id: \"1\"\n    installation_id: 2\n"),
            with_app("    app_id: 1\n    installation_id: 0\n"),
        ] {
            assert!(parse_file(&text).is_err(), "{text}");
        }
        assert!(parse_file(&with_app("    app_id: 1\n    installation_id: 2\n")).is_ok());
    }

    #[test]
    fn a_non_https_api_is_refused_including_loopback_http() {
        for api in [
            "http://api.github.com",
            "http://localhost:8080",
            "http://127.0.0.1",
            "http://[::1]:9",
            "ftp://x.example",
            "api.github.com",
            "HTTPS://api.github.com",
            "",
        ] {
            assert!(parse(&app(api, "t", "k")).is_err(), "{api}");
        }
        assert!(parse(&app("https://localhost:8443", "t", "k")).is_ok());
    }

    #[test]
    fn an_api_with_a_path_query_userinfo_or_fragment_is_refused() {
        for api in [
            "https://api.github.com/v3",
            "https://api.github.com//",
            "https://api.github.com?x=1",
            "https://api.github.com/?x=1",
            "https://u:p@api.github.com",
            "https://u@api.github.com",
            "https://api.github.com#f",
            "https://api.github.com/#f",
            "https://api.github.com\\x",
            "https://",
            "https:///",
            "https://api.github.com:0",
            "https://api.github.com:99999",
            "https://api .github.com",
        ] {
            assert!(ApiBase::parse(api).is_none(), "{api}");
        }
        assert_eq!(
            ApiBase::parse("https://api.github.com/").unwrap().as_str(),
            "https://api.github.com"
        );
        assert_eq!(
            ApiBase::parse("https://api.github.com:8443")
                .unwrap()
                .as_str(),
            "https://api.github.com:8443"
        );
    }

    #[test]
    fn names_outside_their_grammar_are_refused() {
        let long = "a".repeat(65);
        let max = "a".repeat(64);
        let app_name = |n: &str| {
            format!(
                "vault:\n  approle_mount: m\n{X_API}github_apps:\n  \"{n}\":\n    app_id: 1\n    installation_id: 2\n    host: x.example\n    api: https://x.example\n    transit_mount: t\n    transit_key: k\n"
            )
        };
        for n in ["", "Upper", "under_score", "a b", "a/b", "é", long.as_str()] {
            assert!(parse(&app_name(n)).is_err(), "app {n:?}");
        }
        for n in ["a", "a-1", max.as_str()] {
            assert!(parse(&app_name(n)).is_ok(), "app {n:?}");
        }
        for n in ["", "a b", "a/b", "a.b", "é", long.as_str()] {
            assert!(
                parse(&app("https://x.example", &format!("\"{n}\""), "k")).is_err(),
                "mount {n:?}"
            );
            assert!(
                parse(&app("https://x.example", "t", &format!("\"{n}\""))).is_err(),
                "key {n:?}"
            );
            assert!(
                parse(&format!("vault:\n  approle_mount: \"{n}\"\n")).is_err(),
                "approle {n:?}"
            );
        }
        for n in ["A_b-9", max.as_str()] {
            assert!(parse(&app("https://x.example", n, n)).is_ok(), "{n:?}");
        }
    }

    #[test]
    fn the_grammar_edges_are_accepted() {
        for n in ["-a", "a-", "_a", "a_"] {
            assert!(parse(&app("https://x.example", n, n)).is_ok(), "{n:?}");
        }
        for n in ["-a", "a-"] {
            let text = format!(
                "vault:\n  approle_mount: m\n{X_API}github_apps:\n  \"{n}\":\n    app_id: 1\n    installation_id: 2\n    host: x.example\n    api: https://x.example\n    transit_mount: t\n    transit_key: k\n"
            );
            assert!(parse(&text).is_ok(), "app {n:?}");
        }
    }

    #[test]
    fn an_ipv6_literal_host_is_admitted_and_an_unclosed_one_is_not() {
        assert_eq!(
            ApiBase::parse("https://[::1]:8443").unwrap().as_str(),
            "https://[::1]:8443"
        );
        assert!(ApiBase::parse("https://[::1").is_none());
    }

    fn requirement(uid: u32) -> maknae_io::TargetRequired {
        maknae_io::TargetRequired {
            owner: Some(uid),
            ..MINTING_ARTIFACT
        }
    }

    #[test]
    fn a_group_writable_or_non_root_file_is_refused() {
        let ok = write("ok", FULL, 0o640);
        let uid = me(&ok);
        assert!(load_minting_with(&ok, requirement(uid)).unwrap().is_some());
        let ok_ro = write("ok_ro", FULL, 0o440);
        assert!(load_minting_with(&ok_ro, requirement(uid))
            .unwrap()
            .is_some());
        for (name, mode) in [
            ("gw", 0o660),
            ("or", 0o644),
            ("ow", 0o602),
            ("ux", 0o750),
            ("gx", 0o650),
        ] {
            let p = write(name, FULL, mode);
            let got = load_minting_with(&p, requirement(uid));
            let _ = std::fs::remove_file(&p);
            assert!(got.is_err(), "mode {mode:o}");
        }
        let other = load_minting_with(&ok, requirement(uid + 1))
            .unwrap_err()
            .to_string();
        assert!(other.contains(&ok.display().to_string()), "{other}");
        assert!(!other.contains("approle-mint"), "{other}");
        let _ = std::fs::remove_file(&ok);
        let _ = std::fs::remove_file(&ok_ro);
    }

    #[test]
    fn a_minting_yaml_over_64_kib_is_refused_before_it_is_parsed() {
        let pad = |total: usize| {
            let mut text = format!("{FULL}#");
            text.push_str(&"x".repeat(total - text.len() - 1));
            text.push('\n');
            text
        };
        let p = write("cap_edge", &pad(MINTING_MAX_BYTES), 0o640);
        let got = load_minting_with(&p, requirement(me(&p)));
        let _ = std::fs::remove_file(&p);
        assert!(got.unwrap().is_some());
        let p = write("cap_over", &pad(MINTING_MAX_BYTES + 1), 0o640);
        let got = load_minting_with(&p, requirement(me(&p)));
        let _ = std::fs::remove_file(&p);
        let e = got.unwrap_err();
        assert!(!matches!(e, ConfigError::Parse { .. }), "{e:?}");
        assert_eq!(MINTING_MAX_BYTES, 64 * 1024);
        assert_eq!(MINTING_ARTIFACT.max_bytes, Some(64 * 1024));
    }

    fn role_requirement(uid: u32) -> maknae_io::TargetRequired {
        maknae_io::TargetRequired {
            owner: Some(uid),
            ..ROLE_ID_ARTIFACT
        }
    }

    #[test]
    fn a_role_id_is_read_trimmed_from_a_file_held_to_the_minting_owner_and_mode() {
        let ok = write("role_ok", "  5f0c-role.ID_1\n", 0o640);
        let uid = me(&ok);
        assert_eq!(
            load_mint_role_id_with(&ok, role_requirement(uid)).unwrap(),
            "5f0c-role.ID_1"
        );
        for (name, mode) in [("role_gw", 0o660), ("role_or", 0o644), ("role_ux", 0o740)] {
            let p = write(name, "role", mode);
            let got = load_mint_role_id_with(&p, role_requirement(uid));
            let _ = std::fs::remove_file(&p);
            assert!(got.is_err(), "mode {mode:o}");
        }
        assert!(load_mint_role_id_with(&ok, role_requirement(uid + 1)).is_err());
        let _ = std::fs::remove_file(&ok);
        assert!(matches!(
            load_mint_role_id_with(&tmp("role_absent"), role_requirement(uid)),
            Err(ConfigError::NotFound { .. })
        ));
        assert_eq!(MINT_ROLE_ID_FILE, "role-id");
        assert_eq!(ROLE_ID_ARTIFACT.owner, Some(0));
        assert_eq!(ROLE_ID_ARTIFACT.mode_mask, MINTING_ARTIFACT.mode_mask);
    }

    #[test]
    fn a_role_id_outside_its_grammar_is_refused_without_echoing_it() {
        let max = "r".repeat(ROLE_ID_MAX_BYTES);
        let long = "r".repeat(ROLE_ID_MAX_BYTES + 1);
        for (i, text) in ["", " \n", "a b", "SENTINEL\u{e9}", long.as_str(), "a\tb"]
            .into_iter()
            .enumerate()
        {
            let p = write(&format!("role_bad{i}"), text, 0o640);
            let got = load_mint_role_id_with(&p, role_requirement(me(&p)));
            let _ = std::fs::remove_file(&p);
            let e = got.unwrap_err();
            assert!(
                matches!(e, ConfigError::InvalidMintRoleId(_)),
                "{text:?}: {e:?}"
            );
            assert!(!e.to_string().contains("SENTINEL"), "{e}");
        }
        let p = write("role_max", &max, 0o640);
        let got = load_mint_role_id_with(&p, role_requirement(me(&p)));
        let _ = std::fs::remove_file(&p);
        assert_eq!(got.unwrap(), max);
    }

    #[test]
    fn a_role_id_file_is_bounded_before_it_is_read_and_held_to_root() {
        let edge = format!("{}\n\n", "r".repeat(ROLE_ID_MAX_BYTES));
        let p = write("role_edge", &edge, 0o640);
        let got = load_mint_role_id_with(&p, role_requirement(me(&p)));
        let _ = std::fs::remove_file(&p);
        assert_eq!(got.unwrap(), "r".repeat(ROLE_ID_MAX_BYTES));
        let p = write("role_over", &format!("{edge}\n"), 0o640);
        let got = load_mint_role_id_with(&p, role_requirement(me(&p)));
        let _ = std::fs::remove_file(&p);
        let e = got.unwrap_err();
        assert!(
            !matches!(e, ConfigError::InvalidMintRoleId(_)),
            "refused by the read bound, not the grammar: {e:?}"
        );

        let mine = write("role_mine", "role", 0o640);
        let (owner, got) = (me(&mine), load_mint_role_id(&mine));
        let _ = std::fs::remove_file(&mine);
        assert!(
            owner == 0 || got.is_err(),
            "a role-id not owned by root: {got:?}"
        );
        assert!(matches!(
            load_mint_role_id(&tmp("role_absent_public")),
            Err(ConfigError::NotFound { .. })
        ));
    }

    #[test]
    fn a_present_file_that_fails_to_parse_is_an_error_not_none() {
        let p = write("bad", "vault: [\n", 0o640);
        let got = load_minting_with(&p, requirement(me(&p)));
        let _ = std::fs::remove_file(&p);
        assert!(got.is_err());
    }
}
